/* The full Colony and Europe screens. */
import { $, ACT, art, cap, D, L, P, pick, RES, t, W } from '../data.js';
import { icon } from '../icons.js';
import { Board } from '../map/board.js';
import { Sprite } from '../map/sprites.js';
import { Places } from '../places.js';
import { S } from '../state.js';
import { Texts, trait, work } from '../texts.js';
import { fatherCard, lore } from './fans.js';
import { goods, hull } from './goods.js';
export function scenes(sp) {
  const back = `<button class="back" data-close>${t('map')}</button>`, lab = (id) => (S.card ? Places.label(sp[id]) : '');
  if (S.view === 'colony') {
    $('sCol').style.backgroundImage = `url(${art.nation(P.nation)})`;
    const homes = Places.homes(), ys = S.card ? D.yields[S.card] || [] : D.land;
    const land = (home) => { const cells = [-1, 0, 1].flatMap((a) => [-1, 0, 1].map((b) => { const c = home.cell + a * W + b, y = ys.filter((q) => q.cell === c), here = !a && !b, s = sp[`cell:${c}`]; return `<div class="c${here ? ' here' : ''}" ${y.length || Places.tokens(`cell:${c}`) ? `data-space="cell:${c}"` : ''} style="left:${(b + 1) * 33.33}%;top:${(a + 1) * 33.33}%">${here ? `<svg class="town" viewBox="0 0 64 64">${Sprite.colony(home)}</svg>` : ''}${y.map((q) => `<span class="y">${icon(Places.ico(q.icon), 20)}${q.n}</span>`).join('')}${Places.tokens(`cell:${c}`)}</div>`; void s; })).join(''); return `<div class="land"><canvas width="520" height="520" data-home="${home.cell}"></canvas>${cells}<span class="def">${icon('sword', 15)} ${home.defence}</span></div>`; };
    const plans = Object.keys(D.buildings).filter((b) => !P.buildings.includes(b));
    $('sCol').innerHTML = `${back}<div class="in"><h2>${pick(D.names.nations[P.nation])}</h2><div class="two"><div><div class="lands n${homes.length}">${homes.map(land).join('') || `<p>${L('No colony yet. Land your infantry and found one.', 'Колонии пока нет. Высадите пехоту и основайте её.')}</p>`}</div><div class="stores"><div data-space="deck" class="wz"><h4>${t('warehouse')} ${Places.sum(P.wh)}/${D.cap} ${S.card ? `<small>${pick(ACT.supply)}: ${sp.deck?.options ? `${Places.plus(-1, 'food')}, ${L('draw 1', 'взять 1')}` : Places.label(sp.deck)}</small>` : ''}</h4><div class="heap wide">${goods(P.wh).map((r) => `<span>${icon(r, 27)}</span>`).join('')}${'<i></i>'.repeat(Math.max(0, D.cap - Places.sum(P.wh)))}</div></div><div><h4>${t('hold')}</h4>${hull()}</div></div></div><div><h4>${t('buildings')} ${P.buildings.length}/${D.settings.buildings.max}</h4><div class="blds">${P.buildings.map((b) => `<div class="bld" data-space="lot:${b}"><img src="${art.building(b)}" alt=""><span class="tk">${Places.tokens(`lot:${b}`)}</span><div class="cp"><b>${cap(pick(D.buildings[b]))}</b><span>${S.card ? Places.label(sp[`lot:${b}`]) : work(b)}</span></div></div>`).join('') || `<p>${t('none')}</p>`}</div><h4>${t('plans')}</h4><div class="plans">${plans.map((b) => { const s = sp[`build:${b}`]; return `<div class="plan${D.left[b] <= 0 ? ' gone' : ''}" data-space="build:${b}"><img src="${art.building(b)}" alt=""><span class="nm">${cap(pick(D.buildings[b]))}</span><small>${work(b)}</small><em>${S.card && s && !s.options ? (s.wants ? `<span class="lack" title="${s.why}"><img src="${art.building(s.wants)}" alt="${s.why}"></span>` : s.need ? Places.lack(s) : `<small class="no">${s.why}</small>`) : `${s?.cost ?? D.buildings[b].timber}${icon('timber', 15)}`}</em></div>`; }).join('')}</div><h4>${t('fathers')} ${P.fathers.length}/${D.settings.fathers.max}</h4><div class="grid3">${P.fathers.map((f) => fatherCard(f)).join('') || `<p>${t('none')}</p>`}</div></div></div></div>`;
    const T = Board.terrain, k = T.width / W; $('sCol').querySelectorAll('canvas').forEach((c) => { const h = +c.dataset.home, x = (h % W) - 1, y = Math.floor(h / W) - 1; c.getContext('2d').drawImage(T, x * k, y * k, 3 * k, 3 * k, 0, 0, 520, 520); });
  } else $('sCol').innerHTML = '';
  if (S.view === 'europe') {
    $('sEu').innerHTML = `${back}<div class="in"><h2>${t('europe')}</h2><div class="two eu"><div><div class="zone" data-space="eu:market"><h4>${t('market')} ${lab('eu:market')}</h4><div class="mk">${RES.map((r) => `${icon(r, 32)}<span class="bar"><i style="width:${D.price[r] * 20}%"></i></span><b>${D.price[r]}</b><span class="dm" title="${t('demand')}">${D.players.map((_, i) => `<i class="${i < D.demand[r] ? 'on' : ''}"></i>`).join('')}</span>`).join('')}</div><p class="note">${L('When the circles of a good fill, its price falls by 1.', 'Когда кружки товара заполнены, его цена падает на 1.')}</p><div class="hold">${hull()}<span>${L('Worth', 'Стоит')} <b>${Places.worth(S.card)} ${icon('gold', 22)}</b>${Places.inEurope() ? '' : `<br><small>${L('The ship must be in Europe to sell', 'Чтобы продать, корабль должен быть в Европе')}</small>`}</span>${Places.tokens('eu:market')}</div></div>${S.card && sp['eu:some']?.options ? `<div class="tls wide"><div class="tl" data-space="eu:some"><img src="art/crate.webp" alt=""><span><b>${L('Sell some', 'Продать часть')}</b></span></div></div>` : ''}${P.damage ? `<div class="tls wide"><div class="tl" data-space="eu:yard"><img src="${art.building('shipyard')}" alt=""><span><b>${pick(ACT.repair)}</b></span><span class="rs">${lab('eu:yard')}</span></div></div>` : ''}</div><div><h4>${t('pier')} <small>${L('up to 2 per action', 'до 2 за действие')}</small></h4><div class="ppl">${D.pier.map(([x, n]) => `<div class="big${D.agents[x].price > P.gold ? ' dear' : ''}" data-space="pier:${x}"><img src="${art.agent(x)}" alt=""><span class="cost">${icon('gold', 17)}${sp[`pier:${x}`]?.cost ?? D.agents[x].price}</span><b>${pick(D.agents[x])}${n > 1 ? ` ×${n}` : ''}</b><small>${trait(x) || L('no talent', 'без таланта')}</small><span class="tk">${Places.tokens(`pier:${x}`)}</span></div>`).join('')}${S.card ? `<div class="big newp" data-space="pier:new"><span class="rot">↻</span><b>${L('New agents', 'Другие агенты')}</b></div>` : ''}</div><h4 style="margin-top:26px">${t('salon')} <small>${L('up to 2 per action', 'до 2 за действие')}</small></h4><div class="ppl">${D.salon.map((f) => `<div class="big fa${D.fathers[f].bells > P.bells ? ' dear' : ''}" data-space="salon:${f}"><img src="${art.father(f)}" alt=""><span class="cost">${icon('bells', 17)}${D.fathers[f].bells}</span><b>${pick(D.fathers[f])}</b><i class="lore">${lore(f)}</i><small>${Texts.father(f, 15)}</small><span class="tk">${Places.tokens(`salon:${f}`)}</span></div>`).join('')}</div></div></div></div>`;
  } else $('sEu').innerHTML = '';
}
